import json
import os

def find_components(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and (r,c) not in visited:
                comp = []
                stack = [(r,c)]
                visited.add((r,c))
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0<=nr<h and 0<=nc<w and grid[nr][nc]==2 and (nr,nc) not in visited:
                            visited.add((nr,nc))
                            stack.append((nr,nc))
                components.append(comp)
    return components

def solve(grid):
    components = find_components(grid)

    if not components:
        return []

    sorted_comps = sorted(components, key=lambda c: (min([x[0] for x in c]), min([x[1] for x in c])))
    n = len(sorted_comps)

    out_grid = [[0]*6 for _ in range(3)]

    if n >= 4:
        # Top band components → row 0 at cols [0,2,3,5]
        top_cols = [0, 2, 3, 5]
        for i in range(4):
            out_grid[0][top_cols[i]] = 3 if i < 2 else 1

    if n >= 7:
        # Bottom band components → row 2 at cols [0,3,5]
        bottom_cols = [0, 3, 5]
        for i in range(3):
            out_grid[2][bottom_cols[i]] = 3 if i < 1 else 1

    return out_grid

