def find_components(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    background = 0

    components = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background and not visited[r][c]:
                visited[r][c] = True
                comp = [(r, c)]
                stack = [(r, c)]
                while stack:
                    pr, pc = stack.pop()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = pr + dr, pc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] != background:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                                comp.append((nr, nc))
                components.append(comp)

    return components

